import{_ as t,a0 as l,w as o,s as c,ao as d,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"命令行快速技巧：如何定位一个文件 | LCTT x X-CMD","titleTemplate":false,"description":"命令行快速技巧：如何定位一个文件 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行快速技巧：如何定位一个文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行快速技巧：如何定位一个文件 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181105 Commandline quick tips- How to locate a file","title":"命令行快速技巧：如何定位一个文件","tag":"201811","desc":""},"relativePath":"201811/20181105 Commandline quick tips- How to locate a file.md","filePath":"[post].md"}'),r={name:"201811/20181105 Commandline quick tips- How to locate a file.md"};function h(g,s,k,u,b,m){const n=l("Link");return o(),c("div",null,[s[15]||(s[15]=d(`<h1 id="命令行快速技巧-如何定位一个文件" tabindex="-1">命令行快速技巧：如何定位一个文件 <a class="header-anchor" href="#命令行快速技巧-如何定位一个文件" aria-label="Permalink to “命令行快速技巧：如何定位一个文件”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/10/commandlinequicktips-816x345.jpg" alt=""></p><p>我们都会有文件存储在电脑里 —— 目录、相片、源代码等等。它们是如此之多。也无疑超出了我的记忆范围。要是毫无目标，找到正确的那一个可能会很费时间。在这篇文章里我们来看一下如何在命令行里找到需要的文件，特别是快速找到你想要的那一个。</p><p>好消息是 Linux 命令行专门设计了很多非常有用的命令行工具在你的电脑上查找文件。下面我们看一下它们其中三个：<code>ls</code>、<code>tree</code> 和 <code>find</code>。</p><h3 id="ls" tabindex="-1">ls <a class="header-anchor" href="#ls" aria-label="Permalink to “ls”">​</a></h3><p>如果你知道文件在哪里，你只需要列出它们或者查看有关它们的信息，<code>ls</code> 就是为此而生的。</p><p>只需运行 <code>ls</code> 就可以列出当下目录中所有可见的文件和目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Documents Music Pictures Videos notes.txt</span></span></code></pre></div><p>添加 <code>-l</code> 选项可以查看文件的相关信息。同时再加上 <code>-h</code> 选项，就可以用一种人们易读的格式查看文件的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh</span></span>
<span class="line"><span>total 60K</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:07 Documents</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:07 Music</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:13 Pictures</span></span>
<span class="line"><span>drwxr-xr-x 2 adam adam 4.0K Nov 2 13:07 Videos</span></span>
<span class="line"><span>-rw-r--r-- 1 adam adam 43K Nov 2 13:12 notes.txt</span></span></code></pre></div><p><code>ls</code> 也可以搜索一个指定位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls Pictures/</span></span>
<span class="line"><span>trees.png wallpaper.png</span></span></code></pre></div><p>或者一个指定文件 —— 即便只跟着名字的一部分：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls *.txt</span></span>
<span class="line"><span>notes.txt</span></span></code></pre></div><p>少了点什么？想要查看一个隐藏文件？没问题，使用 <code>-a</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>. .bash_logout .bashrc Documents Pictures notes.txt</span></span>
<span class="line"><span>.. .bash_profile .vimrc Music Videos</span></span></code></pre></div><p><code>ls</code> 还有很多其他有用的选项，你可以把它们组合在一起获得你想要的效果。可以使用以下命令了解更多：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man ls</span></span></code></pre></div><h3 id="tree" tabindex="-1">tree <a class="header-anchor" href="#tree" aria-label="Permalink to “tree”">​</a></h3><p>如果你想查看你的文件的树状结构，<code>tree</code> 是一个不错的选择。可能你的系统上没有默认安装它，你可以使用包管理 DNF 手动安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install tree</span></span></code></pre></div><p>如果不带任何选项或者参数地运行 <code>tree</code>，将会以当前目录开始，显示出包含其下所有目录和文件的一个树状图。提醒一下，这个输出可能会非常大，因为它包含了这个目录下的所有目录和文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- Documents</span></span>
<span class="line"><span>| |-- notes.txt</span></span>
<span class="line"><span>| |-- secret</span></span>
<span class="line"><span>| | \`-- christmas-presents.txt</span></span>
<span class="line"><span>| \`-- work</span></span>
<span class="line"><span>| |-- project-abc</span></span>
<span class="line"><span>| | |-- README.md</span></span>
<span class="line"><span>| | |-- do-things.sh</span></span>
<span class="line"><span>| | \`-- project-notes.txt</span></span>
<span class="line"><span>| \`-- status-reports.txt</span></span>
<span class="line"><span>|-- Music</span></span>
<span class="line"><span>|-- Pictures</span></span>
<span class="line"><span>| |-- trees.png</span></span>
<span class="line"><span>| \`-- wallpaper.png</span></span>
<span class="line"><span>|-- Videos</span></span>
<span class="line"><span>\`-- notes.txt</span></span></code></pre></div><p>如果列出的太多了，使用 <code>-L</code> 选项，并在其后加上你想查看的层级数，可以限制列出文件的层级：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree -L 2</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- Documents</span></span>
<span class="line"><span>| |-- notes.txt</span></span>
<span class="line"><span>| |-- secret</span></span>
<span class="line"><span>| \`-- work</span></span>
<span class="line"><span>|-- Music</span></span>
<span class="line"><span>|-- Pictures</span></span>
<span class="line"><span>| |-- trees.png</span></span>
<span class="line"><span>| \`-- wallpaper.png</span></span>
<span class="line"><span>|-- Videos</span></span>
<span class="line"><span>\`-- notes.txt</span></span></code></pre></div><p>你也可以显示一个指定目录的树状图：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree Documents/work/</span></span>
<span class="line"><span>Documents/work/</span></span>
<span class="line"><span>|-- project-abc</span></span>
<span class="line"><span>| |-- README.md</span></span>
<span class="line"><span>| |-- do-things.sh</span></span>
<span class="line"><span>| \`-- project-notes.txt</span></span>
<span class="line"><span>\`-- status-reports.txt</span></span></code></pre></div><p>如果使用 <code>tree</code> 列出的是一个很大的树状图，你可以把它跟 <code>less</code> 组合使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree | less</span></span></code></pre></div><p>再一次，<code>tree</code> 有很多其他的选项可以使用，你可以把他们组合在一起发挥更强大的作用。man 手册页有所有这些选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man tree</span></span></code></pre></div><h3 id="find" tabindex="-1">find <a class="header-anchor" href="#find" aria-label="Permalink to “find”">​</a></h3><p>那么如果不知道文件在哪里呢？就让我们来找到它们吧！</p><p>要是你的系统中没有 <code>find</code>，你可以使用 DNF 安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install findutils</span></span></code></pre></div><p>运行 <code>find</code> 时如果没有添加任何选项或者参数，它将会递归列出当前目录下的所有文件和目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>./Documents</span></span>
<span class="line"><span>./Documents/secret</span></span>
<span class="line"><span>./Documents/secret/christmas-presents.txt</span></span>
<span class="line"><span>./Documents/notes.txt</span></span>
<span class="line"><span>./Documents/work</span></span>
<span class="line"><span>./Documents/work/status-reports.txt</span></span>
<span class="line"><span>./Documents/work/project-abc</span></span>
<span class="line"><span>./Documents/work/project-abc/README.md</span></span>
<span class="line"><span>./Documents/work/project-abc/do-things.sh</span></span>
<span class="line"><span>./Documents/work/project-abc/project-notes.txt</span></span>
<span class="line"><span>./.bash_logout</span></span>
<span class="line"><span>./.bashrc</span></span>
<span class="line"><span>./Videos</span></span>
<span class="line"><span>./.bash_profile</span></span>
<span class="line"><span>./.vimrc</span></span>
<span class="line"><span>./Pictures</span></span>
<span class="line"><span>./Pictures/trees.png</span></span>
<span class="line"><span>./Pictures/wallpaper.png</span></span>
<span class="line"><span>./notes.txt</span></span>
<span class="line"><span>./Music</span></span></code></pre></div><p>但是 <code>find</code> 真正强大的是你可以使用文件名进行搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -name do-things.sh</span></span>
<span class="line"><span>./Documents/work/project-abc/do-things.sh</span></span></code></pre></div><p>或者仅仅是名字的一部分 —— 像是文件后缀。我们来找一下所有的 .txt 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -name &quot;*.txt&quot;</span></span>
<span class="line"><span>./Documents/secret/christmas-presents.txt</span></span>
<span class="line"><span>./Documents/notes.txt</span></span>
<span class="line"><span>./Documents/work/status-reports.txt</span></span>
<span class="line"><span>./Documents/work/project-abc/project-notes.txt</span></span>
<span class="line"><span>./notes.txt</span></span></code></pre></div><p>你也可以根据大小寻找文件。如果你的空间不足的时候，这种方法也许特别有用。现在来列出所有大于 1 MB 的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -size +1M</span></span>
<span class="line"><span>./Pictures/trees.png</span></span>
<span class="line"><span>./Pictures/wallpaper.png</span></span></code></pre></div><p>当然也可以搜索一个具体的目录。假如我想在我的 Documents 文件夹下找一个文件，而且我知道它的名字里有 “project” 这个词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find Documents -name &quot;*project*&quot;</span></span>
<span class="line"><span>Documents/work/project-abc</span></span>
<span class="line"><span>Documents/work/project-abc/project-notes.txt</span></span></code></pre></div><p>除了文件它还显示目录。你可以限制仅搜索查询文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find Documents -name &quot;*project*&quot; -type f</span></span>
<span class="line"><span>Documents/work/project-abc/project-notes.txt</span></span></code></pre></div><p>最后再一次，<code>find</code> 还有很多供你使用的选项，要是你想使用它们，man 手册页绝对可以帮到你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man find</span></span></code></pre></div><hr>`,50)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://fedoramagazine.org/commandline-quick-tips-locate-file/"},{default:i(()=>[...s[0]||(s[0]=[a("https://fedoramagazine.org/commandline-quick-tips-locate-file/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://fedoramagazine.org/author/asamalik/"},{default:i(()=>[...s[2]||(s[2]=[a("Adam Šamalík",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/dianbanjiu"},{default:i(()=>[...s[4]||(s[4]=[a("dianbanjiu",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=t(r,[["render",h]]);export{y as __pageData,C as default};
